import { act } from '@testing-library/react-native';
import { useAuthStore } from '../stores/authStore';
import { authService } from '../services/authService';

// Mock du service d'authentification
jest.mock('../services/authService', () => ({
  authService: {
    login: jest.fn(),
  },
}));

describe('authStore', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    // Réinitialiser le store avant chaque test
    useAuthStore.setState({ user: null, token: null, isAuthenticated: false });
  });

  test('login should store token and user data on success', async () => {
    const mockResponse = {
      token: 'fake-jwt-token',
      user: { id: '123', name: 'Jean', email: 'jean@example.com' },
    };

    (authService.login as jest.Mock).mockResolvedValue(mockResponse);

    await act(async () => {
      await useAuthStore.getState().login('jean@example.com', 'password123');
    });

    const state = useAuthStore.getState();
    expect(state.token).toBe('fake-jwt-token');
    expect(state.user).toEqual(mockResponse.user);
    expect(state.isAuthenticated).toBe(true);
  });

  test('login should handle errors', async () => {
    (authService.login as jest.Mock).mockRejectedValue(new Error('Invalid credentials'));

    await act(async () => {
      try {
        await useAuthStore.getState().login('jean@example.com', 'wrong-password');
      } catch (error) {
        // L'erreur doit être propagée
      }
    });

    const state = useAuthStore.getState();
    expect(state.token).toBeNull();
    expect(state.user).toBeNull();
    expect(state.isAuthenticated).toBe(false);
  });
});
