```typescript
import { authService } from '../services/authService';
import api from '../services/api';

// Mock du module api
jest.mock('../services/api', () => ({
  post: jest.fn(),
}));

describe('authService', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  test('login should call the correct endpoint and return user data', async () => {
    const mockResponse = {
      data: {
        token: 'fake-jwt-token',
        user: { id: '123', name: 'Jean', email: 'jean@example.com' },
      },
    };

    (api.post as jest.Mock).mockResolvedValue(mockResponse);

    const result = await authService.login('jean@example.com', 'password123');

    expect(api.post).toHaveBeenCalledWith('/auth/login', {
      email: 'jean@example.com',
      password: 'password123',
    });
    expect(result).toEqual(mockResponse.data);
  });

  test('login should throw an error when credentials are invalid', async () => {
    const mockError = {
      response: {
        status: 401,
        data: { message: 'Invalid credentials' },
      },
    };

    (api.post as jest.Mock).mockRejectedValue(mockError);

    await expect(
      authService.login('jean@example.com', 'wrong-password')
    ).rejects.toThrow('Email ou mot de passe incorrect');
  });
});
